package com.sarc.backend.model;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.*;
@Entity @Table(name="citas",uniqueConstraints=@UniqueConstraint(name="uk_medico_fecha_hora",columnNames={"medico_id","fecha","hora"})) public class Cita { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Usuario paciente; @ManyToOne(optional=false) private Usuario medico; @ManyToOne private Usuario recepcionista; @NotNull private LocalDate fecha; @NotNull private LocalTime hora; private String motivo,observaciones; @Enumerated(EnumType.STRING) private Enums.EstadoCita estado=Enums.EstadoCita.PROGRAMADA; public Long getId(){return id;} public Usuario getPaciente(){return paciente;} public void setPaciente(Usuario v){paciente=v;} public Usuario getMedico(){return medico;} public void setMedico(Usuario v){medico=v;} public void setRecepcionista(Usuario v){recepcionista=v;} public LocalDate getFecha(){return fecha;} public void setFecha(LocalDate v){fecha=v;} public LocalTime getHora(){return hora;} public void setHora(LocalTime v){hora=v;} public String getMotivo(){return motivo;} public void setMotivo(String v){motivo=v;} public Enums.EstadoCita getEstado(){return estado;} public void setEstado(Enums.EstadoCita v){estado=v;} }
